(function () {
  try {
    var params = new URLSearchParams(window.location.search);
    var fromAdmin = params.get("from") === "administration";
    var school = (params.get("school") || "scmcs").toLowerCase();
    var role = (params.get("role") || "student").toLowerCase();
    var name = params.get("name") || "";
    var email = params.get("email") || "";
    var number = params.get("number") || "";
    var course = params.get("course") || "";
    var org = params.get("org") || "";

    if (fromAdmin) {
      document.body.classList.add("from-administration");
      document.querySelectorAll("nav a.active").forEach(function (el) {
        el.classList.remove("active");
      });
      var adminLink = document.querySelector('nav a[href="/admin/administration"]');
      if (adminLink) {
        adminLink.classList.add("active");
        adminLink.hidden = false;
        adminLink.removeAttribute("hidden");
      }
      var title = document.getElementById("info-title");
      var subtitle = document.getElementById("info-subtitle");
      if (title) title.textContent = "Administration";
      if (subtitle) subtitle.textContent = "Admin Details";
      document.title = "Admin Details | DC Space Admin";

      var adminSummary = document.getElementById("admin-event-summary");
      var adminActions = document.getElementById("admin-details-actions");
      if (adminSummary) {
        adminSummary.hidden = false;
        adminSummary.removeAttribute("hidden");
      }
      if (adminActions) {
        adminActions.hidden = false;
        adminActions.removeAttribute("hidden");
      }
    }

    var back = document.getElementById("info-back");
    if (back) {
      var backHref =
        "/admin/school30?school=" +
        encodeURIComponent(school) +
        "&role=" +
        encodeURIComponent(role);
      if (fromAdmin) backHref += "&from=administration";
      back.href = backHref;
      back.setAttribute(
        "aria-label",
        fromAdmin ? "Back to Administration school users" : "Back to school users"
      );
    }

    function setVal(id, value) {
      var el = document.getElementById(id);
      if (!el || !value) return;
      if ("value" in el) el.value = value;
      else el.textContent = value;
    }
    setVal("field-name", name);
    setVal("field-email", email);
    setVal("field-number", number);
    setVal("field-course", course);
    setVal("field-org", org);

    var userNameEl = document.getElementById("user-name");
    var userEmailEl = document.getElementById("user-email");
    if (userNameEl && name) userNameEl.textContent = name;
    if (userEmailEl && email) userEmailEl.textContent = email;
    else if (userEmailEl && name) {
      var slug = name
        .toLowerCase()
        .replace(/[^a-z]+/g, ".")
        .replace(/^\.|\.$/g, "");
      userEmailEl.textContent = slug + "@sdca.edu.ph";
    }
  } catch (err) {}
})();

(function () {
        const app = document.getElementById("app");
        const menuToggle = document.getElementById("menu-toggle");
        const brandLogo = document.getElementById("brand-logo");
        const params = new URLSearchParams(window.location.search);
        const school = params.get("school") || "scmcs";
        const role = params.get("role") || "student";
        const name = params.get("name") || "Khrystelle Jan G. Esplana";
        const email =
          params.get("email") ||
          name
            .toLowerCase()
            .replace(/[^a-z\s.]/g, "")
            .trim()
            .replace(/\s+/g, ".")
            .replace(/\.+/g, ".") + "@sdca.edu.ph";
        const number = params.get("number") || "20XX-XXXXX";
        const course = params.get("course") || "Bachelor of Science in Information Technology";
        const org = params.get("org") || "DOMINIXODE";
        const orgRole = params.get("orgRole") || "Organization Officer";
        const orgPos = params.get("orgPos") || "President";

        const schools = {
          sase: "School of Accountancy, Science, and Education",
          scmcs: "School of Communication, Multimedia, and Computer Studies",
          snahs: "School of Nursing and Allied Health Studies",
          smls: "School of Medical Laboratory Sciences",
          sihtm: "School of International Hospitality, Tourism, and Management",
        };

        const setText = (id, text) => {
          const el = document.getElementById(id);
          if (!el) return;
          if (el.tagName === "INPUT" || el.tagName === "TEXTAREA") {
            el.value = text;
          } else {
            el.textContent = text;
          }
        };

        setText("user-name", name);
        setText("user-email", email);
        setText("field-name", name);
        setText("field-email", email);
        setText("field-number", number);
        setText("field-course", course);
        setText("field-school", schools[school] || schools.scmcs);
        setText("field-org", org);
        setText("field-org-role", orgRole);
        setText("field-org-pos", orgPos);

        const initials = name
          .split(/\s+/)
          .filter(Boolean)
          .slice(0, 2)
          .map((p) => p[0])
          .join("")
          .toUpperCase();
        setText("user-initials", initials || "U");

        const back = document.getElementById("info-back");
        if (back) {
          var __fromAdmin = (params.get("from") === "administration");
          back.href =
            "/admin/school30?school=" +
            encodeURIComponent(school) +
            "&role=" +
            encodeURIComponent(role) +
            (__fromAdmin ? "&from=administration" : "");
        }

        function updateInfoUrl() {
          const q = new URLSearchParams({
            school,
            role,
            name: document.getElementById("field-name")?.value?.trim() || name,
            email: document.getElementById("field-email")?.value?.trim() || email,
            number: document.getElementById("field-number")?.value?.trim() || number,
            course: document.getElementById("field-course")?.value?.trim() || course,
            org: document.getElementById("field-org")?.value?.trim() || org,
            orgRole: document.getElementById("field-org-role")?.value?.trim() || "Organization Officer",
            orgPos: document.getElementById("field-org-pos")?.value?.trim() || "President",
          });
          return "/admin/perinfo31?" + q.toString();
        }

        /* in-place edit: no route to perinfo31 */

        const eregLink = document.getElementById("events-registered-link");
        if (eregLink) {
          const q = new URLSearchParams(params);
          eregLink.href = "/admin/ereg32?" + q.toString();
        }

        const eattendLink = document.getElementById("events-attended-link");
        if (eattendLink) {
          const q = new URLSearchParams(params);
          eattendLink.href = "/admin/eattend33?" + q.toString();
        }

        const eorgaLink = document.getElementById("events-organized-link");
        if (eorgaLink) {
          const q = new URLSearchParams(params);
          eorgaLink.href = "/admin/eorga35?" + q.toString();
        }

        const esavedLink = document.getElementById("events-saved-link");
        if (esavedLink) {
          const q = new URLSearchParams(params);
          esavedLink.href = "/admin/esaved37?" + q.toString();
        }

        const certLink = document.getElementById("certificates-earned-link");
        if (certLink) {
          const q = new URLSearchParams(params);
          certLink.href = "/admin/cert38?" + q.toString();
        }

        const fbLink = document.getElementById("feedback-submitted-link");
        if (fbLink) {
          const q = new URLSearchParams(params);
          fbLink.href = "/admin/fb39?" + q.toString();
        }

        /* toggle handled by controls script */

        function setSidebarCollapsed(collapsed) {
          app.classList.toggle("sidebar-collapsed", collapsed);
          menuToggle.setAttribute("aria-expanded", collapsed ? "false" : "true");
          menuToggle.setAttribute(
            "aria-label",
            collapsed ? "Expand sidebar" : "Collapse sidebar"
          );
          brandLogo.setAttribute(
            "aria-label",
            collapsed ? "Expand sidebar" : "DC Space"
          );
        }

        menuToggle.addEventListener("click", () => {
          setSidebarCollapsed(!app.classList.contains("sidebar-collapsed"));
        });

        brandLogo.addEventListener("click", () => {
          if (app.classList.contains("sidebar-collapsed")) {
            setSidebarCollapsed(false);
          }
        });
      })();

(function () {
  const toggle = document.getElementById("user-menu-toggle");
  const popover = document.getElementById("user-menu-popover");
  const logoutBtn = document.getElementById("user-menu-logout");
  if (!toggle || !popover) return;

  function closeMenu() {
    popover.hidden = true;
    toggle.setAttribute("aria-expanded", "false");
  }

  function openMenu() {
    popover.hidden = false;
    toggle.setAttribute("aria-expanded", "true");
  }

  toggle.addEventListener("click", function (event) {
    event.preventDefault();
    event.stopPropagation();
    if (popover.hidden) openMenu();
    else closeMenu();
  });

  document.addEventListener("click", function (event) {
    if (!event.target.closest(".user-menu")) closeMenu();
  });

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape") closeMenu();
