;(function () {
  try {
    function syncStatus(row) {
      if (!row) return;
      var check = row.querySelector(".perm-check");
      var status = row.querySelector(".perm-status");
      if (!check || !status) return;
      if (check.checked) {
        status.textContent = "ALLOWED";
        status.classList.add("allowed");
        status.classList.remove("denied");
      } else {
        status.textContent = "NOT ALLOWED";
        status.classList.add("denied");
        status.classList.remove("allowed");
      }
    }

    function syncAllRows() {
      document.querySelectorAll("#perms-list .perm-row").forEach(syncStatus);
    }

    function setAllAllowed(allowed) {
      document.querySelectorAll("#perms-list .perm-check").forEach(function (c) {
        c.checked = !!allowed;
      });
      document.querySelectorAll("#perms-list .perm-group").forEach(function (g) {
        g.classList.add("open");
        var chev = g.querySelector(":scope > .perm-row .perm-chevron");
        if (chev) chev.setAttribute("aria-expanded", "true");
      });
      syncAllRows();
    }

    function refreshAllowAllButton() {
      var allowAll = document.getElementById("perms-allow-all");
      if (!allowAll) return;
      var checks = Array.prototype.slice.call(
        document.querySelectorAll("#perms-list .perm-check")
      );
      var allOn = checks.length > 0 && checks.every(function (c) { return c.checked; });
      allowAll.classList.toggle("is-active", allOn);
      allowAll.setAttribute("aria-pressed", allOn ? "true" : "false");
      var span = allowAll.querySelector(".allow-all-text");
      if (span) span.textContent = allOn ? "All Allowed" : "Allow All";
    }

    document.querySelectorAll(".perm-chevron").forEach(function (btn) {
      btn.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        var group = btn.closest(".perm-group");
        if (!group) return;
        group.classList.toggle("open");
        btn.setAttribute(
          "aria-expanded",
          group.classList.contains("open") ? "true" : "false"
        );
      });
    });

    document.querySelectorAll("#perms-list .perm-row").forEach(function (row) {
      var check = row.querySelector(".perm-check");
      if (!check) return;
      syncStatus(row);
      check.addEventListener("change", function () {
        syncStatus(row);
        var group = row.closest(".perm-group");
        if (group && row.parentElement === group) {
          group.querySelectorAll(".perm-children .perm-check").forEach(function (child) {
            child.checked = check.checked;
            syncStatus(child.closest(".perm-row"));
          });
        }
        refreshAllowAllButton();
      });
    });

    setAllAllowed(false);
    refreshAllowAllButton();

    var allowAll = document.getElementById("perms-allow-all");
    if (allowAll) {
      allowAll.type = "button";
      allowAll.dataset.boundAllow = "1";
      allowAll.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        var turningOn = !allowAll.classList.contains("is-active");
        setAllAllowed(turningOn);
        refreshAllowAllButton();
      });
    }
  } catch (err) {
    console.error("permissions script", err);
  }
})();

(function () {
  try {
    var card = document.getElementById("personal-info-card");
    var editBtn = document.getElementById("edit-personal-info");
    var saveBtn = document.getElementById("save-personal-info");
    var cancelBtn = document.getElementById("cancel-personal-info");
    if (!card || !editBtn) return;

    var inputs = Array.prototype.slice.call(
      card.querySelectorAll(".value-input")
    );
    var snapshot = {};

    function takeSnapshot() {
      snapshot = {};
      inputs.forEach(function (input) {
        snapshot[input.id] = input.value;
      });
    }

    function restoreSnapshot() {
      inputs.forEach(function (input) {
        if (snapshot[input.id] != null) input.value = snapshot[input.id];
      });
    }

    function setEditing(on) {
      card.classList.toggle("is-editing", on);
      inputs.forEach(function (input) {
        if (on) input.removeAttribute("readonly");
        else input.setAttribute("readonly", "readonly");
      });
      if (saveBtn) {
        if (on) {
          saveBtn.hidden = false;
          saveBtn.removeAttribute("hidden");
        } else {
          saveBtn.hidden = true;
        }
      }
      if (cancelBtn) {
        if (on) {
          cancelBtn.hidden = false;
          cancelBtn.removeAttribute("hidden");
        } else {
          cancelBtn.hidden = true;
        }
      }
      if (on && inputs[0]) inputs[0].focus();
    }

    function syncBanner() {
      var name = document.getElementById("field-name");
      var email = document.getElementById("field-email");
      var userName = document.getElementById("user-name");
      var userEmail = document.getElementById("user-email");
      var initials = document.getElementById("user-initials");
      if (userName && name) userName.textContent = name.value.trim() || userName.textContent;
      if (userEmail && email) userEmail.textContent = email.value.trim() || userEmail.textContent;
      if (initials && name) {
        var parts = name.value.trim().split(/\s+/).filter(Boolean);
        initials.textContent = parts
          .slice(0, 2)
          .map(function (p) { return p.charAt(0).toUpperCase(); })
          .join("") || "U";
      }
    }

    // Prevent any leftover navigation
    editBtn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      takeSnapshot();
      setEditing(true);
    });

    if (saveBtn) {
      saveBtn.addEventListener("click", function () {
        syncBanner();
        takeSnapshot();
        setEditing(false);
      });
    }

    if (cancelBtn) {
      cancelBtn.addEventListener("click", function () {
        restoreSnapshot();
        setEditing(false);
      });
    }

    // Start locked
    setEditing(false);
    takeSnapshot();
  } catch (err) {}
})();

/* dc-space controls: suspend + allow-all */
;(function () {
  try {
    function setSuspended(on) {
      document.querySelectorAll('.toggle[aria-label="Suspend Account"]').forEach(function (btn) {
        btn.classList.toggle("on", !!on);
        btn.setAttribute("aria-pressed", on ? "true" : "false");
      });
      var statusValue = document.getElementById("account-status-value");
      if (statusValue) statusValue.textContent = on ? "Suspended" : "Active";
      document.querySelectorAll(".status-list .info-field").forEach(function (field) {
        var label = field.querySelector(".label");
        var value = field.querySelector(".value");
        if (!label || !value) return;
        if ((label.textContent || "").trim().toLowerCase() === "status") {
          value.textContent = on ? "Suspended" : "Active";
        }
      });
    }

    document.querySelectorAll('.toggle[aria-label="Suspend Account"]').forEach(function (btn) {
      if (btn.dataset.boundSuspend === "1") return;
      btn.dataset.boundSuspend = "1";
      btn.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        setSuspended(!btn.classList.contains("on"));
      });
    });

    var allowAll = document.getElementById("perms-allow-all");
    if (allowAll && allowAll.dataset.boundAllow !== "1") {
      allowAll.dataset.boundAllow = "1";
      allowAll.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        var turningOn = !allowAll.classList.contains("is-active");
        document.querySelectorAll("#perms-list .perm-check").forEach(function (c) {
          c.checked = turningOn;
        });
        document.querySelectorAll("#perms-list .perm-group").forEach(function (g) {
          g.classList.add("open");
        });
        document.querySelectorAll("#perms-list .perm-row").forEach(function (row) {
          var check = row.querySelector(".perm-check");
          var status = row.querySelector(".perm-status");
          if (!check || !status) return;
          if (check.checked) {
            status.textContent = "ALLOWED";
            status.classList.add("allowed");
            status.classList.remove("denied");
          } else {
            status.textContent = "NOT ALLOWED";
            status.classList.add("denied");
            status.classList.remove("allowed");
          }
        });
        allowAll.classList.toggle("is-active", turningOn);
        allowAll.setAttribute("aria-pressed", turningOn ? "true" : "false");
        var span = allowAll.querySelector(".allow-all-text");
        if (span) span.textContent = turningOn ? "All Allowed" : "Allow All";
      });
    }
  } catch (err) {
    console.error("controls script", err);
  }
})();

/* dc-space: delete account confirm modal */
;(function () {
  try {
    var overlay = document.getElementById("delete-account-overlay");
    var backBtn = document.getElementById("delete-account-back");
    var yesBtn = document.getElementById("delete-account-yes");
    if (!overlay) return;

    function openModal() {
      overlay.hidden = false;
      overlay.removeAttribute("hidden");
      document.body.classList.add("delete-modal-open");
      if (yesBtn) yesBtn.focus();
    }

    function closeModal() {
      overlay.hidden = true;
      overlay.setAttribute("hidden", "");
      document.body.classList.remove("delete-modal-open");
    }

    document.querySelectorAll("#delete-account-btn, #delete-account-btn-participant, .delete-account-row").forEach(function (btn) {
      if (btn.dataset.boundDelete === "1") return;
      btn.dataset.boundDelete = "1";
      btn.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        openModal();
      });
    });

    if (backBtn) {
      backBtn.addEventListener("click", function (e) {
        e.preventDefault();
        closeModal();
      });
    }

    if (yesBtn) {
      yesBtn.addEventListener("click", function (e) {
        e.preventDefault();
        closeModal();
        // Prototype: after confirm, return to previous school/admin list
        try {
          var params = new URLSearchParams(window.location.search);
          var school = params.get("school") || "scmcs";
          var role = params.get("role") || "student";
          var fromAdmin = params.get("from") === "administration";
          var href =
            "/admin/school30?school=" +
            encodeURIComponent(school) +
            "&role=" +
            encodeURIComponent(role) +
            (fromAdmin ? "&from=administration" : "");
          window.location.href = href;
        } catch (err) {
          window.history.back();
        }
      });
    }

    overlay.addEventListener("click", function (e) {
      if (e.target === overlay) closeModal();
    });

    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && !overlay.hidden) closeModal();
    });
  } catch (err) {
    console.error("delete modal script", err);
  }
})();
